class Solution {
public:
    bool isValid(string s) {
        unordered_map<char, char> pairs = {{')', '('}, {']', '['}, {'}', '{'}};
        vector<char> stack;
        for (char ch : s) {
            if (pairs.count(ch)) {                      // 右括号
                if (stack.empty() || stack.back() != pairs[ch]) {
                    return false;
                }
                stack.pop_back();
            } else {                                    // 左括号
                stack.push_back(ch);
            }
        }
        return stack.empty();
    }
};

