func isValid(s string) bool {
	pairs := map[byte]byte{')': '(', ']': '[', '}': '{'}
	stack := []byte{}
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if open, ok := pairs[ch]; ok { // 右括号
			if len(stack) == 0 || stack[len(stack)-1] != open {
				return false
			}
			stack = stack[:len(stack)-1]
		} else { // 左括号
			stack = append(stack, ch)
		}
	}
	return len(stack) == 0
}

