class Solution {
public:
    bool isValid(string s) {
        auto has = [&](const string& p) { return s.find(p) != string::npos; };
        while (has("()") || has("[]") || has("{}")) {
            for (string p : {"()", "[]", "{}"}) {       // 依次删掉每一种相邻的一对
                string t;
                for (size_t i = 0; i < s.size(); i++) {
                    if (s.compare(i, 2, p) == 0) i++;   // 跳过这一对
                    else t += s[i];
                }
                s = t;
            }
        }
        return s.empty();
    }
};

