build(a, snap) {
    const s = a.s, pairs = { ")": "(", "]": "[", "}": "{" }, stack = [];
    const view = (i, opts = {}) => [
      {
        t: "array",
        label: "s",
        items: [...s].map((v, t) => ({
          v,
          cls: t === i || t === opts.matchIdx ? (opts.bad ? "b" : opts.matched ? "c" : "a") : t < i ? "d" : "",
        })),
        ptrs: { i: i >= 0 && i < s.length ? i : null },
      },
      {
        t: "chips",
        label: "栈（右边是栈顶）",
        items: stack.map((it, t) => ({
          v: it.ch,
          cls: opts.justPushed && t === stack.length - 1 ? "a" : "e",
        })),
        empty: "空",
      },
    ];
    let prevCh = "—";
    snap("开始", "从左往右看每个字符，栈一开始是空的。", view(-1), {
      at: "init",
      facts: [["当前字符", "—"], ["栈顶", "空"], ["栈大小", 0]],
    });
    for (let i = 0; i < s.length; i++) {
      const ch = s[i];
      const oldTop = stack.length ? stack[stack.length - 1].ch : "空";
      const oldLen = stack.length;
      if (!(ch in pairs)) {
        stack.push({ ch, idx: i });
        snap("压栈", `'${ch}' 是左括号，压进栈里，等它的右括号。`, view(i, { justPushed: true }), {
          at: "push",
          facts: [["当前字符", ch, prevCh], ["栈顶", ch, oldTop], ["栈大小", stack.length, oldLen]],
        });
        prevCh = ch;
        continue;
      }
      if (!stack.length) {
        snap("无效", `'${ch}' 是右括号，但栈是空的，前面没有左括号能和它配。返回 false。`, view(i, { bad: true }), {
          at: ["match", "bad"],
          kind: "warn",
          ans: false,
          facts: [["当前字符", ch, prevCh], ["栈顶", "空"], ["栈大小", 0]],
        });
        return;
      }
      const popped = stack.pop();
      if (popped.ch !== pairs[ch]) {
        snap("无效", `'${ch}' 是右括号，栈顶是 '${popped.ch}'，不是同一种括号。返回 false。`, view(i, { matchIdx: popped.idx, bad: true }), {
          at: ["match", "bad"],
          kind: "warn",
          ans: false,
          facts: [["当前字符", ch, prevCh], ["栈顶", popped.ch], ["栈大小", oldLen]],
        });
        return;
      }
      const newTop = stack.length ? stack[stack.length - 1].ch : "空";
      snap("配对", `'${ch}' 是右括号，栈顶正好是 '${popped.ch}'，配上了，弹出栈顶。`, view(i, { matchIdx: popped.idx, matched: true }), {
        at: "match",
        kind: "ok",
        facts: [["当前字符", ch, prevCh], ["栈顶", newTop, popped.ch], ["栈大小", stack.length, oldLen]],
      });
      prevCh = ch;
    }
    const finalTop = stack.length ? stack[stack.length - 1].ch : "空";
    if (stack.length) {
      snap("无效", `字符串走完了，但栈里还剩 ${stack.length} 个左括号没关上。返回 false。`, view(s.length), {
        at: "done",
        kind: "warn",
        ans: false,
        facts: [["当前字符", "—", prevCh], ["栈顶", finalTop], ["栈大小", stack.length]],
      });
    } else {
      snap("完成", "字符串走完，栈也空了，每个括号都配上了。返回 true。", view(s.length), {
        at: "done",
        kind: "ok",
        ans: true,
        facts: [["当前字符", "—", prevCh], ["栈顶", "空"], ["栈大小", 0]],
      });
    }
  }

