        facts: [["轮数", round], ["本轮删对数", 0], ["剩余长度", s.length]],
      });
      while (has()) {
        const prevRound = round;
        round++;
        let roundDel = 0;
        for (const p of ["()", "[]", "{}"]) {
          const hl = new Set();
          for (let k = s.indexOf(p); k >= 0; k = s.indexOf(p, k + 2)) { hl.add(k); hl.add(k + 1); }
          if (!hl.size) continue;
          const cnt = hl.size / 2;
          const oldLen = s.length;
          snap(`第 ${round} 轮`, `找到 ${cnt} 对相邻的 <code>${p}</code>，全部删掉。`, view(hl), {
            at: "del",
            facts: [["轮数", round, prevRound], ["删掉对数", cnt, roundDel], ["剩余长度", oldLen]],
          });
          roundDel += cnt;
          s = s.split(p).join("");
        }
        snap(`第 ${round} 轮完`, s.length ? (has() ? `删完变成 "${s}"，里面又出现了相邻的一对，再来一轮。` : `删完变成 "${s}"，已经没有相邻的一对了。`) : "删成空串了。", view(new Set()), {
